<script>
document.addEventListener('DOMContentLoaded',function(){
 const money=v=>'Rp '+Number(v||0).toLocaleString('id-ID',{maximumFractionDigits:0}),escapeHtml=v=>String(v??'—').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
 const reportUrl=@json(route('home.get_earnings_data')),tabs=document.querySelectorAll('.earn-tab'),panels={summary:document.getElementById('earn-summary-panel'),report:document.getElementById('earn-report-panel')};let reportLoaded=false,currentPage=1,lastPage=1;
 const filters={period:document.getElementById('report-period'),quarter:document.getElementById('report-quarter'),platform:document.getElementById('report-platform'),region:document.getElementById('report-region'),release:document.getElementById('report-release'),search:document.getElementById('report-search')};
 const params=page=>{const p=new URLSearchParams({page});Object.entries(filters).forEach(([key,input])=>{if(input.value)p.set(key,input.value)});return p};
 const render=data=>{const s=data.summary||{},rows=data.results||[],total=Number(s.total_earnings||0);document.getElementById('report-summary').innerHTML=`<div class="report-summary-icon"><span class="material-icons-outlined">account_balance_wallet</span></div><div><span>Total penghasilan terfilter</span><strong>${money(s.total_earnings)}</strong></div><div><span>Jumlah laporan</span><b>${Number(s.report_count||0).toLocaleString('id-ID')} laporan</b></div><div><span>Total stream</span><b>${Number(s.total_streams||0).toLocaleString('id-ID')}</b></div><div><span>Filter aktif</span><b>${filters.period.value||'Semua tahun'}</b></div>`;document.getElementById('report-table-body').innerHTML=rows.length?rows.map(r=>`<tr><td>${escapeHtml(r.sales_month||r.period)}</td><td>${escapeHtml(r.period)}</td><td>${escapeHtml(r.release_title||'—')}</td><td>${escapeHtml(r.track_title||'—')}</td><td>${escapeHtml(r.platform)}</td><td>${escapeHtml(r.region_name||r.region||'—')}</td><td>${escapeHtml(r.views)}</td><td>${money(r.rupiah_raw)}</td></tr>`).join(''):'<tr><td colspan="8" class="report-loading">Tidak ada laporan untuk filter ini.</td></tr>';const platforms=data.platforms||[];document.getElementById('report-platform-list').innerHTML=platforms.length?platforms.map(p=>{const share=total?Number(p.earnings)/total*100:0;return `<div class="report-platform-row"><strong>${escapeHtml(p.platform||'Tanpa platform')}</strong><b>${money(p.earnings)}</b><span class="platform-meter"><i style="width:${Math.min(share,100)}%"></i></span><small>${share.toLocaleString('id-ID',{maximumFractionDigits:1})}%</small></div>`}).join(''):'<p class="report-loading">Tidak ada data platform.</p>';currentPage=data.pagination?.current_page||1;lastPage=data.pagination?.last_page||1;document.getElementById('report-count').textContent=`Menampilkan ${rows.length} dari ${Number(data.pagination?.total||0).toLocaleString('id-ID')} laporan`;document.getElementById('report-page').textContent=currentPage;document.getElementById('report-prev').disabled=currentPage<=1;document.getElementById('report-next').disabled=currentPage>=lastPage};
 const load=async(page=1)=>{document.getElementById('report-table-body').innerHTML='<tr><td colspan="8" class="report-loading">Memuat laporan…</td></tr>';try{const response=await fetch(`${reportUrl}?${params(page)}`,{headers:{Accept:'application/json'}});if(!response.ok)throw Error();render(await response.json());reportLoaded=true}catch(e){document.getElementById('report-table-body').innerHTML='<tr><td colspan="8" class="report-loading">Laporan tidak dapat dimuat. Coba lagi.</td></tr>'}};
 tabs.forEach(tab=>tab.addEventListener('click',()=>{const key=tab.dataset.tab;tabs.forEach(x=>x.classList.toggle('is-active',x===tab));Object.entries(panels).forEach(([name,panel])=>panel.classList.toggle('is-active',name===key));if(key==='report'&&!reportLoaded)load()}));document.querySelectorAll('[data-open-report]').forEach(b=>b.addEventListener('click',()=>document.querySelector('[data-tab="report"]').click()));document.getElementById('report-apply').addEventListener('click',()=>load(1));document.getElementById('report-prev').addEventListener('click',()=>currentPage>1&&load(currentPage-1));document.getElementById('report-next').addEventListener('click',()=>currentPage<lastPage&&load(currentPage+1));let timer;filters.search.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>load(1),350)});document.getElementById('report-export').addEventListener('click',()=>{const form=document.getElementById('report-export-form');form.querySelectorAll('input[name]:not([name="_token"])').forEach(i=>i.remove());params(1).forEach((value,key)=>{if(key!=='page'){const input=document.createElement('input');input.type='hidden';input.name=key;input.value=value;form.appendChild(input)}});form.submit()});
 const node=document.getElementById('earnings-bars');if(!node||typeof echarts==='undefined')return;const chart=echarts.init(node),months=JSON.parse(document.getElementById('earn-months').textContent),values=JSON.parse(document.getElementById('earn-values').textContent);chart.setOption({grid:{left:52,right:16,top:16,bottom:40},tooltip:{trigger:'axis',backgroundColor:'#162536',borderColor:'#3b4f69',textStyle:{color:'#f7fafc'},formatter:i=>`<b>${i[0].axisValue}</b><br>${i[0].marker} Penghasilan: <b>${money(i[0].value)}</b>`},xAxis:{type:'category',data:months,axisLine:{lineStyle:{color:'#3b4d64'}},axisLabel:{color:'#9db0c7',fontSize:10}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#263950'}},axisLabel:{color:'#9db0c7',fontSize:10,formatter:v=>Number(v).toLocaleString('id-ID',{notation:'compact'})}},series:[{name:'Penghasilan',type:'bar',data:values,barMaxWidth:35,itemStyle:{color:'#43d395',borderRadius:[4,4,0,0]}}]});window.addEventListener('resize',()=>chart.resize())
});
</script>
@endpush
